{
  "appearance_facts": [
    {
      "location": "Upper left title area, roughly x=10-1100, y=40-90",
      "fact": "The map title reads “Incidence of Condition A in US States,” which does not match the task’s “prevalence” wording."
    },
    {
      "location": "Right-side legend, roughly x=1780-1870, y=740-1150",
      "fact": "A vertical color scale runs from a dark red bottom labeled “Low” to a pale yellow top labeled “High,” with tick values 0, 20, 40, 60, 80, and 100."
    },
    {
      "location": "Florida, southeastern US, roughly x=1530-1660, y=1050-1300",
      "fact": "Florida is filled with the darkest red on the map, matching the lowest end of the legend."
    },
    {
      "location": "Iowa, central US, roughly x=990-1110, y=540-640",
      "fact": "Iowa is also filled with a very dark red, visually similar to Florida’s darkest category."
    },
    {
      "location": "Wyoming, mountain west, roughly x=490-740, y=430-610",
      "fact": "Wyoming is filled with a very dark red, visually similar to Iowa and Florida."
    },
    {
      "location": "Idaho, northwest, roughly x=300-440, y=220-510",
      "fact": "Idaho is filled with a very dark red, visually similar to Iowa, Wyoming, and Florida."
    },
    {
      "location": "New Hampshire, northeast, roughly x=1730-1780, y=400-460",
      "fact": "New Hampshire is filled with a pale yellow, matching the high end of the legend."
    },
    {
      "location": "Delaware, mid-Atlantic, roughly x=1690-1720, y=650-690",
      "fact": "Delaware is filled with a pale yellow, matching the high end of the legend."
    }
  ],
  "printed_facts": [
    {
      "location": "Map title",
      "fact": "Printed title: “Incidence of Condition A in US States.”"
    },
    {
      "location": "Legend top",
      "fact": "Legend label: “High” with tick value 100."
    },
    {
      "location": "Legend bottom",
      "fact": "Legend label: “Low” with tick value 0."
    },
    {
      "location": "Legend intermediate ticks",
      "fact": "Printed tick values: 20, 40, 60, and 80 between Low and High."
    },
    {
      "location": "State labels for candidate options",
      "fact": "Candidate state labels visible on the map: “NH” in New Hampshire, “FL” in Florida, and “DE” in Delaware."
    },
    {
      "location": "Other dark-red state labels",
      "fact": "Other states labeled with the darkest red include “IA,” “WY,” and “ID.”"
    },
    {
      "location": "Other pale-yellow state labels",
      "fact": "Other states labeled with pale yellow include “WA,” “MT,” “TX,” “NY,” and “ME.”"
    },
    {
      "location": "No numeric annotations",
      "fact": "No per-state numeric values are printed on the map; only state abbreviations and the legend scale are shown."
    }
  ],
  "public_definitions": [
    "The task asks to “open the state statistics view that should be routed into the highest-prevalence priority follow-up workflow.”",
    "The dashboard is designated as “the evidence source for the state priority view routing decision.”",
    "The primary field is labeled “Highest-prevalence state statistics route.”"
  ],
  "uncertain": [
    "The chart title says “Incidence,” while the task and form refer to “prevalence”; it is unclear whether the dashboard is intended to serve as the prevalence evidence source despite the title mismatch.",
    "The legend’s color-to-value direction is ambiguous: “High” is at the top with 100 and “Low” at the bottom with 0, but the darkest red is at the bottom near “Low,” so it is unclear whether darkest red represents the highest or lowest prevalence/incidence.",
    "No exact numeric values are provided for any state, so the relative ranking among the darkest-red states (FL, IA, WY, ID) cannot be determined from the chart alone."
  ]
}
